(()=>{let e="system";try{const t=localStorage.getItem("sg-theme");["light","dark","system"].includes(t)&&(e=t)}catch{}const c=e==="dark"||e==="system"&&matchMedia("(prefers-color-scheme: dark)").matches;document.documentElement.dataset.theme=c?"dark":"light",document.documentElement.dataset.themePreference=e})();
